function reportHtml(){const T=W[CUR.lang],a=CUR.a,R=CUR.R,X=KK().TX[CUR.lang],A=AK().L[CUR.lang];const g=R.gr;const NAK=P().NAK;
  const rows=AK().ORDER.map(k=>{const x=g[k];return `<tr><td><b>${A.pl[k]}</b>${x.retro?" ℞":""}</td><td>${A.rashi[x.sign]}</td><td class="num">${Math.floor(x.deg)}°</td><td>${NAK[x.nak]} ${x.pada}</td><td class="num">${x.house}</td><td>${X.dig[x.dig]||""}</td></tr>`}).join("");
  return `<div class="kun rep" lang="${CUR.lang}"><div class="gan-top">${ganesh()}<div><div class="kun-inv">${X.h.inv}</div><p class="gshl">${GSHLOKA}</p></div></div><h2 class="kun-t">${X.h.title} — ${esc(R.b.name)}</h2>${kundaliHtml()}
   <h3>${T.hdr.age}</h3><p>${esc(a.age)}</p>${dp("par")}<h3>${T.hdr.child}</h3>${li([...a.child,a.edu])}<h3>${T.hdr.past}</h3>${li(a.pastEv)}
   <h3>${T.hdr.mar}</h3>${li(a.marr)}${dp("mar")}<h3>${T.hdr.pro}</h3><p><b>${T.pro.field}</b> ${esc(a.fields)}</p>${dp("car")}${dp("gro")}${a.sade.length?li(a.sade):""}
   <h3>${T.hdr.now}</h3>${li(a.nowL)}<h3>${T.hdr.fut}</h3>${li(a.futA)}${dp("hea")}<p><b>${T.fut.focus}</b> ${esc(a.focus.join(" · "))}</p><h3>${T.hdr.rem}</h3>${li([...a.rem,a.gen])}${J.jyLifeHtml(R,["stages","rel","car","hea","life","num"],CUR.lang)}<p class="kun-note">${X.h.note}</p></div>`}
const open=i=>{CUR.step=i;J.closeDrawer?.();const d=J.drawer({title:"🕉 "+KK().TX[CUR.lang].h.title,wide:true,body:`<div class="jy-pop" lang="${CUR.lang}">${stepHtml(i)}</div>`});if(d)d.style.width="min(980px,100%)"};
