const PIN={};async function geoPin(pin){if(PIN[pin])return PIN[pin];let place="",state="",lat=null,lon=null;
  try{const r=await fetch("https://api.postalpincode.in/pincode/"+pin).then(r=>r.json());const po=r?.[0]?.PostOffice?.[0];if(po){place=po.District||po.Name;state=po.State}}catch(e){}
  for(const q of ["postalcode="+pin+"&country=India",place?"q="+encodeURIComponent(place+", "+state+", India"):""].filter(Boolean)){try{const r=await fetch("https://nominatim.openstreetmap.org/search?format=json&limit=1&"+q,{headers:{"Accept-Language":"en"}}).then(r=>r.json());if(r?.[0]){lat=+(+r[0].lat).toFixed(4);lon=+(+r[0].lon).toFixed(4);if(!place)place=(r[0].display_name||"").split(",").slice(0,2).join(",").trim();break}}catch(e){}}
  return PIN[pin]=lat!=null?{place:place+(state?", "+state:""),lat,lon}:null}
