const loadJs=src=>new Promise((ok,no)=>{if(document.querySelector(`script[src="${src}"]`))return ok();const s=document.createElement("script");s.src=src;s.onload=ok;s.onerror=()=>no(new Error("Could not load "+src));document.head.appendChild(s)});
async function makePdf(){await loadJs("https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js");await loadJs("https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js");
  const box=document.createElement("div");box.style.cssText="position:fixed;left:-10000px;top:0;width:760px;background:#FFF59D;padding:24px;font-family:'Noto Serif','Noto Serif Devanagari','Noto Serif Bengali',Georgia,serif;color:#B71C1C;line-height:1.5;text-align:justify";await gResolve();box.innerHTML=reportHtml();document.body.appendChild(box);await gFill();await document.fonts?.ready;await Promise.all([...box.querySelectorAll("img")].map(im=>im.complete&&im.naturalWidth?0:new Promise(r=>{im.onload=im.onerror=r;setTimeout(r,8000)})));
  try{const cv=await window.html2canvas(box,{scale:2,backgroundColor:"#FFF59D",useCORS:true});const {jsPDF}=window.jspdf;const pdf=new jsPDF({unit:"mm",format:"a4"});const pw=210,ph=297,m=8;const w=pw-2*m;const pxPerMm=cv.width/w;const pageH=Math.floor((ph-2*m)*pxPerMm);
    for(let y=0,i=0;y<cv.height;y+=pageH,i++){const c=document.createElement("canvas");c.width=cv.width;c.height=Math.min(pageH,cv.height-y);c.getContext("2d").drawImage(cv,0,y,cv.width,c.height,0,0,cv.width,c.height);if(i)pdf.addPage();pdf.setDrawColor(183,28,28);pdf.setLineWidth(.8);pdf.rect(4,4,pw-8,ph-8);pdf.addImage(c.toDataURL("image/jpeg",.9),"JPEG",m,m,w,c.height/pxPerMm)}
    return pdf.output("blob")}finally{box.remove()}}
